---CalcCardCombatEffectiveness
---计算卡牌战力
---@param entity CardProgressionEntity
---@param extParams table
---@param cb fun(vo: AttrDefinesVo, v: number, index:number | nil)
---@param providerCombatEffInfoCb fun(providerType: Constants.AttributeProviderType, providerCombatEff: number)
function FormulaUtils.CalcCardCombatEffectiveness(entity, extParams, cb, providerCombatEffInfoCb)
    ClearTable(attrId2TotalV)
    ClearTable(attrId2TotalConstants)
    ClearTable(attrId2CardBasicTotalConstants)
    ClearTable(providerAttrId2AttrAddTypeConfig)
    ClearTable(providerCombatEff2AddTypeConfig)

    ---重新赋值 比 ClearTable快
    -- attrId2TotalV = {}
    -- attrId2TotalConstants = {}
    -- providerAttrId2AttrAddTypeConfig = {}
    -- providerCombatEff2AddTypeConfig = {}
    

    return FormulaUtils.CalcCardCombatEffectivenessByGlobalCache(entity, extParams, cb, providerCombatEffInfoCb, 
        attrId2TotalV, attrId2TotalConstants, attrId2CardBasicTotalConstants, providerAttrId2AttrAddTypeConfig, providerCombatEff2AddTypeConfig)
   
end

function FormulaUtils.CalcCardCombatEffectivenessByGlobalCache(entity, extParams, cb, providerCombatEffInfoCb, 
    attrId2TotalV, attrId2TotalConstants, attrId2CardBasicTotalConstants, providerAttrId2AttrAddTypeConfig, providerCombatEff2AddTypeConfig)
    ClearTable(attrProvider2AttrAddId2V)
    -- attrProvider2AttrAddId2V = nil

    ---@type CardProgressionCombatEffUtils
    local utils                           = GetCombatEffUtils()
    local CalcAttributeValue1             = utils.CalcAttributeValueByTotalConstants
    local CalcAttributeValue2             = utils.CalcAttributeValueBySelfConstants
    local FloorAttributeValue             = utils.FloorAttributeValue
    
    local totalCombatEff = 0
    local attrId2Vo      = GetAttrId2AttrDefineVo()
    
    --- 计算养成战力提供者的属性和战力
    providerAttrId2AttrAddTypeConfig, attrId2TotalConstants, attrId2CardBasicTotalConstants = utils.GeneratedProviderAttrId2AttrAddTypeConfig(entity, extParams, providerAttrId2AttrAddTypeConfig, attrId2TotalConstants, attrId2CardBasicTotalConstants, attrProvider2AttrAddId2V)

    for providerType, attrIdAttrAddTypeConfig in pairs(providerAttrId2AttrAddTypeConfig) do
        local providerCombatEff = 0
        local isEquip = providerType == Constants.AttributeProviderType.Equipment
        local isWeapon = providerType == Constants.AttributeProviderType.Weapon
        for attrId, attrAddTypeConfig in pairs(attrIdAttrAddTypeConfig) do
            local attrV = isEquip and CalcAttributeValue2(attrAddTypeConfig) or CalcAttributeValue1(attrAddTypeConfig, isWeapon and (attrId2CardBasicTotalConstants[attrId] or 0) or (attrId2TotalConstants[attrId] or 0))
            ---@type AttrDefinesVo
            local vo              = attrId2Vo[attrId]
            local basicV         = FloorAttributeValue(attrV, vo.isPercent)
            providerCombatEff     = providerCombatEff + vo.combatEff * basicV
            attrId2TotalV[attrId] = (attrId2TotalV[attrId] or 0) + basicV
        end

        providerCombatEff = floor(providerCombatEff)
        totalCombatEff    = totalCombatEff + providerCombatEff

        if providerCombatEffInfoCb then
            providerCombatEffInfoCb(providerType, providerCombatEff)
        end
    end

    providerAttrId2AttrAddTypeConfig, providerCombatEff2AddTypeConfig = utils.GenerateExtraCombatEffProvider(entity, extParams, providerAttrId2AttrAddTypeConfig, providerCombatEff2AddTypeConfig)

    --- 计算附加战力提供者的属性和战力
    --- 属性战力 = 取整((取整(卡牌养成属性) + 取整(羁绊属性) + 取整(猫球属性)) * 战力系数)
    local CalcExtraAttributeValue     = utils.CalcExtraAttributeValue
    --- 不想没加一个附加战力就加个配置 就 把providerAttrId2AttrAddTypeConfig 和 providerCombatEff2AddTypeConfig的 key table.merge下
    local extraCombatEffProviderTypes = GetExtraCombatEffProviderTypes()
    for index, providerType in ipairs(extraCombatEffProviderTypes) do
        local attrId2AttrAddTypeConfig = providerAttrId2AttrAddTypeConfig[providerType]
        local providerCombatEff = 0
        --- 拥有配置并且不参与 养成属性计算
        if attrId2AttrAddTypeConfig and providerType >= Constants.AttributeProviderType.Skill then
            for attrId, attrAddTypeConfig in pairs(attrId2AttrAddTypeConfig) do
                local totalAttrV      = attrId2TotalV[attrId] or 0
                ---@type AttrDefinesVo
                local vo              = attrId2Vo[attrId]

                local baseTotalAttrV  = FloorAttributeValue(totalAttrV, vo.isPercent)
                ---@type AttrDefinesVo
                local vo              = attrId2Vo[attrId]
                local newTotalAttrV   = CalcExtraAttributeValue(baseTotalAttrV, attrAddTypeConfig)
                if newTotalAttrV > totalAttrV then
                    newTotalAttrV         = FloorAttributeValue(newTotalAttrV, vo.isPercent)
                    attrId2TotalV[attrId] = newTotalAttrV
    
                    local attrV           = newTotalAttrV - baseTotalAttrV
                    providerCombatEff     = providerCombatEff + vo.combatEff * FloorAttributeValue(attrV, vo.isPercent)
                end
            end
            
            totalCombatEff    = totalCombatEff + providerCombatEff

        end

        local combatEffAddTypeConfig  = providerCombatEff2AddTypeConfig[providerType]
        if combatEffAddTypeConfig then
            local oldTotalCombatEff = FloorAttributeValue(totalCombatEff, false)
            totalCombatEff          = CalcExtraAttributeValue(oldTotalCombatEff, combatEffAddTypeConfig)
            providerCombatEff       = providerCombatEff + totalCombatEff - oldTotalCombatEff

        end

        if providerCombatEffInfoCb then
            providerCombatEffInfoCb(providerType, providerCombatEff, true)
        end
    end

    --- 存在收集总属性 才处理
    if cb then
        FormulaUtils.WalkAttrId2V(attrId2TotalV, true, cb)
    end

    return floor(totalCombatEff), attrId2TotalV
end

function FormulaUtils.WalkAttrId2V(attrId2V, isShowAllBaseAttr, cb)
    if isShowAllBaseAttr then
        ---@type AttrDefinesVo[]
        local attrDefinesVos = CardConfMgr:GetInstance():GetBasicAttrs()
        for index, vo in ipairs(attrDefinesVos) do
            if cb then
                local res = cb(vo, attrId2V[vo.id] or 0, index)
                if res == 0 then
                    break
                end
            end
        end
    else
        local attrId2Vo      = GetAttrId2AttrDefineVo()
        for attrId, value in pairs(attrId2V) do
            ---@type AttrDefinesVo
            local vo = attrId2Vo[attrId]
            if cb then
                local res = cb(vo, value)
                if res == 0 then
                    break
                end
            end
        end

    end
   
end

--- CalcCardCombatEffectiveness
--- 计算装备的总战斗力值 
---@param dojo EquipDojo 
---@param cardId integer
---@return number @ 战力值
function FormulaUtils.CalcEquipDojoCombatEffectiveness(dojo)
    ---@type CardProgressionCombatEffUtils
    local utils                    = GetCombatEffUtils()
    local attrAddId2V              = utils.CalcEquipmentPropertyByDojo(dojo, {})
    local attrId2AttrAddTypeConfig = utils.GeneratedAttrId2AttrAddTypeConfig(attrAddId2V) 
    local CalcAttributeValue       = utils.CalcAttributeValueBySelfConstants
    local FloorAttributeValue      = utils.FloorAttributeValue
    local attrId2Vo                = GetAttrId2AttrDefineVo()
    local totalCombatEff = 0
    for attrId, addTypeConfig in pairs(attrId2AttrAddTypeConfig) do
        local attrV = CalcAttributeValue(addTypeConfig)
        ---@type AttrDefinesVo
        local vo   = attrId2Vo[attrId]
        if vo then
            totalCombatEff = totalCombatEff + vo.combatEff * FloorAttributeValue(attrV, vo.isPercent)
        end
    end

    ---添加装备星级战力
    totalCombatEff = totalCombatEff + utils.CalcEquipmentCombatEffectiveness(dojo)

    return floor(totalCombatEff)

end

---CompareCombatEffectivenessAndAttr
---@param preDojo CardDojo
---@param dojo CardDojo
---@param cb fun(vo:AttrDefinesVo, preAttrV:number, attrV:number, index:number):void
---@param preExtParams table
---@param extParams table
function FormulaUtils.CompareCombatEffectivenessAndAttr(preDojo, dojo, cb, preExtParams, extParams)
    ---@type CardProgressionUtils
    local utils     = GetUtils()
    local preEntity = utils.GenerateEntityByCardDojo(preDojo)
    local entity    = utils.GenerateEntityByCardDojo(dojo)
    
    return FormulaUtils.CalcCardCombatEffectivenessAndCompareAttr(preEntity, entity, cb, preExtParams, extParams)
end

---CalcCardCombatEffectivenessAndCompareAttr
---计算卡牌战力并且比较基础属性
---@param preEntity CardProgressionEntity
---@param entity CardProgressionEntity
---@param cb fun(vo:AttrDefinesVo, preAttrV:number, attrV:number, index:number):void
---@param preExtParams table
---@param extParams table
function FormulaUtils.CalcCardCombatEffectivenessAndCompareAttr(preEntity, entity, cb, preExtParams, extParams)
    ---@type CardProgressionCombatEffUtils
    local utils                    = GetCombatEffUtils()
    local preTotalCombatEff, totalCombatEff, preProviderCombatEff2AddTypeConfig, providerCombatEff2AddTypeConfig = FormulaUtils.CompareBasicAttrsByEntity(preEntity, entity, cb, preExtParams, extParams)

     --- 添加其他模块（羁绊 猫球）提供战力
     local isExistPre = preProviderCombatEff2AddTypeConfig ~= nil
     local isExist    = providerCombatEff2AddTypeConfig ~= nil
     if isExistPre or isExist then
        local CalcExtraAttributeValue = utils.CalcExtraAttributeValue
        local extraProviderTypes      = GetExtraCombatEffProviderTypes()
        for key, providerType in ipairs(extraProviderTypes) do
            if isExistPre then
                local addTypeConfig = preProviderCombatEff2AddTypeConfig[providerType]
                if addTypeConfig then
                    preTotalCombatEff      = CalcExtraAttributeValue(preTotalCombatEff, addTypeConfig)
                end    
            end

            if isExist then
                local addTypeConfig = providerCombatEff2AddTypeConfig[providerType]
                if addTypeConfig then
                    totalCombatEff      = CalcExtraAttributeValue(totalCombatEff, addTypeConfig)
                end
            end
        end
         
     end

    return preTotalCombatEff, totalCombatEff
end

