--- CompareBasicAttrs
---@param preCardDojo CardDojo
---@param cardDojo CardDojo
---@param cb function
---@param preExtParams table
---@param extParams table
---@param isRobot boolean
function FormulaUtils.CompareBasicAttrs(preCardDojo, cardDojo, cb, preExtParams, extParams, isRobot)
    preExtParams    = preExtParams or {}
    extParams       = extParams or {}
    ---@type CardProgressionUtils
    local utils     = GetUtils()
    local preEntity = utils.GenerateEntity(preCardDojo, isRobot)
    local entity    = utils.GenerateEntity(cardDojo, isRobot)
    return FormulaUtils.CompareBasicAttrsByEntity(preEntity, entity, cb, preExtParams, extParams)
    
end

function FormulaUtils.CompareBasicAttrsByEntity(preEntity, entity, cb, preExtParams, extParams)
    ClearTable(attrId2TotalV)
    ClearTable(attrId2TotalConstants)
    ClearTable(attrId2CardBasicTotalConstants)
    ClearTable(providerAttrId2AttrAddTypeConfig)
    ClearTable(providerCombatEff2AddTypeConfig)

    
    local totalCombatEff, attrId2TotalV = FormulaUtils.CalcCardCombatEffectivenessByGlobalCache(entity, extParams, nil, nil, 
    attrId2TotalV, attrId2TotalConstants, attrId2CardBasicTotalConstants, providerAttrId2AttrAddTypeConfig, providerCombatEff2AddTypeConfig)
    
    ClearTable(preAttrId2TotalV)
    ClearTable(attrId2TotalConstants)
    ClearTable(attrId2CardBasicTotalConstants)
    ClearTable(providerAttrId2AttrAddTypeConfig)
    ClearTable(providerCombatEff2AddTypeConfig)
    local preTotalCombatEff, preAttrId2TotalV = FormulaUtils.CalcCardCombatEffectivenessByGlobalCache(preEntity, preExtParams, nil, nil, 
        preAttrId2TotalV, attrId2TotalConstants, attrId2CardBasicTotalConstants, providerAttrId2AttrAddTypeConfig, providerCombatEff2AddTypeConfig)

    if cb then
        FormulaUtils.WalkCompareAttrId2V(preAttrId2TotalV, attrId2TotalV , cb)
    end

    return floor(preTotalCombatEff), floor(totalCombatEff)
    
end


function FormulaUtils.WalkCompareAttrId2V(preAttrId2TotalV, attrId2TotalV, cb)
    ---@type AttrDefinesVo[]
    local attrDefinesVos = CardConfMgr:GetInstance():GetBasicAttrs()
    for index, vo in ipairs(attrDefinesVos) do
        if cb then
            local attrId = vo.id
            cb(vo, preAttrId2TotalV[attrId] or 0, attrId2TotalV[attrId] or 0, index)
        end
    end
   
end


return FormulaUtils